const listActiveTaskIDsForAcquisition = `-- name: ListActiveTaskIDsForAcquisition :many
SELECT task.id
FROM episode_tasks AS task
WHERE task.acquisition_id = $1
  AND task.state NOT IN ('imported', 'rejected', 'cancelled')
ORDER BY task.id
`

func (q *Queries) ListActiveTaskIDsForAcquisition(ctx context.Context, acquisitionID pgtype.UUID) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, listActiveTaskIDsForAcquisition, acquisitionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTaskOperationSummaries = `-- name: ListTaskOperationSummaries :many
SELECT id, kind, resource_type, resource_id, idempotency_key, status, river_job_id, max_attempts, attempt_count, timeout_seconds, cancel_requested_at, heartbeat_at, error_code, error_message, payload, created_at, started_at, finished_at, updated_at
FROM operations
WHERE resource_type = 'episode_task'
  AND resource_id = ANY($1::uuid[])
ORDER BY resource_id, created_at DESC, id DESC
`

func (q *Queries) ListTaskOperationSummaries(ctx context.Context, taskIds []pgtype.UUID) ([]Operation, error) {
	rows, err := q.db.Query(ctx, listTaskOperationSummaries, taskIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Operation{}
	for rows.Next() {
		var i Operation
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.ResourceType,
			&i.ResourceID,
			&i.IdempotencyKey,
			&i.Status,
			&i.RiverJobID,
			&i.MaxAttempts,
			&i.AttemptCount,
			&i.TimeoutSeconds,
			&i.CancelRequestedAt,
			&i.HeartbeatAt,
			&i.ErrorCode,
			&i.ErrorMessage,
			&i.Payload,
			&i.CreatedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

