// sqlc nullable projection: optional workflow rows use zero scalar sentinels.
func (q *Queries) ListTaskViews(ctx context.Context, arg ListTaskViewsParams) ([]ListTaskViewsRow, error) {
	rows, err := q.db.Query(ctx, listTaskViews,
		arg.StateFilter,
		arg.PhaseFilter,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTaskViewsRow{}
	for rows.Next() {
		var i ListTaskViewsRow
		if err := rows.Scan(
			&i.ID,
			&i.AcquisitionID,
			&i.SourceVideoFileID,
			&i.MappingID,
			&i.TranscodeProfileID,
			&i.State,
			&i.VideoState,
			&i.SubtitleState,
			&i.Version,
			&i.ErrorCode,
			&i.ErrorMessage,
			&i.LegacyID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.FailureStage,
			&i.MediaType,
			&i.WorkflowAcquisitionID,
			&i.DownloadID,
			&i.SourceSeason,
			&i.SourceEpisode,
			&i.SourceEpisodeFractionHundredths,
			&i.SeriesTitle,
			&i.ReleaseYear,
			&i.TargetSeason,
			&i.TargetEpisode,
			&i.TargetEpisodeTitle,
			&i.ArtifactSetID,
			&i.ArtifactBasename,
			&i.VideoArtifactID,
			&i.VideoFilePath,
			&i.VideoFormat,
			&i.VideoSizeBytes,
			&i.VideoChecksumSha256,
			&i.SubtitleArtifactID,
			&i.SubtitleFilePath,
			&i.SubtitleFormat,
			&i.SubtitleSizeBytes,
			&i.SubtitleChecksumSha256,
			&i.ReviewID,
			&i.ReviewDecision,
			&i.ReviewNotes,
			&i.ReviewedBy,
			&i.ReviewedAt,
			&i.ImportID,
			&i.ImportAttempt,
			&i.ImportStatus,
			&i.DestinationVideoPath,
			&i.DestinationSubtitlePath,
			&i.ImportErrorCode,
			&i.ImportErrorMessage,
			&i.ImportStartedAt,
			&i.ImportCompletedAt,
			&i.ImportCreatedAt,
			&i.ImportUpdatedAt,
			&i.CleanupID,
			&i.CleanupAttempt,
			&i.CleanupStatus,
			&i.TorrentRemoved,
			&i.StagedFilesRemoved,
			&i.CleanupErrorCode,
			&i.CleanupErrorMessage,
			&i.CleanupStartedAt,
			&i.CleanupCompletedAt,
			&i.CleanupCreatedAt,
			&i.CleanupUpdatedAt,
			&i.EmbyItemID,
			&i.EmbyLibraryID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

